 c.addEventListener('pointerup',e=>{let d=studio.pick.down;if(!d)return;let r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(Math.hypot(x-d.x,y-d.y)>6)return;let cand=pickCandidates(),best=null;for(let q of cand){let dist=Math.hypot(x-q.x,y-q.y);if(dist<=19&&(!best||dist+q.priority*1.5<best.score))best={...q,score:dist+q.priority*1.5}}if(best)select(best.type,best.id)},true)
