 let edges=DATA.graph.edges.map(e=>{let a=pos[e.source],b=pos[e.target],on=sel.type==='graphEdge'&&sel.id===e.id;return `<path data-ge="${esc(e.id)}" class="${on?'sel':''}" d="M${a.x},${a.y} C${a.x+55},${a.y} ${b.x-55},${b.y} ${b.x},${b.y}"/>`}).join('');
 let nodes=DATA.graph.nodes.map(n=>{let p=pos[n.id],on=sel.type==='graphNode'&&sel.id===n.id;return `<g data-gn="${esc(n.id)}" class="${on?'sel':''}"><rect x="${p.x-52}" y="${p.y-12}" width="104" height="24" rx="5"/><text x="${p.x}" y="${p.y+3}">${esc(n.label)}</text></g>`}).join('');
