function enter(){
 // Authoring path: dismiss the usability launcher, cleanly leave RIDE, switch to a paused Free Road body, then own the viewport.
 $('v1282Launcher')?.classList.remove('open');
 let nav=$('v123Nav'),active=String(D.body?.dataset?.v123Page||'').toUpperCase();if(active==='RIDE')nav?.querySelector('button[data-v123-page="DYNAMICS"]')?.click();
 try{global.DUCATI_V5_API?.setDomain?.('FREE_ROAD');global.DUCATI_V5_API?.stepFree?.(1)}catch(_){}
 D.body.dataset.v123Page='RIDER_STUDIO';global.__LUCID_ACTIVE_PAGE__='RIDER_STUDIO';global.__LUCID_PERF_MODE__='LAB';
 nav?.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.v123Page==='RIDER_STUDIO'));D.querySelectorAll('.v125Page').forEach(x=>x.classList.remove('on'));
 renderAll()
}
