function keyboard(e){
 if(global.__LUCID_ACTIVE_PAGE__!=='RIDER_STUDIO')return;let tag=e.target?.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT')return;
 if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'){e.preventDefault();e.shiftKey?redo():undo()}
 if(e.code==='KeyF'){e.preventDefault();studio.outlinerFilter='';let q=$('v12855OutSearch');q?.focus()}
 if(e.code==='Digit1')camera('side');if(e.code==='Digit2')camera('persp');if(e.code==='Digit3')camera('front');if(e.code==='Digit4')camera('rear')
}
